BEGIN;

-- ============================================================================
-- 0011_geo_thana_expansion.sql
-- Extends the geo reference data used by checkout and admin order entry:
--   * 5 upazilas approved by NICAR on 2026-05-07 (ids 495-499)
--   * 108 metropolitan police thanas (ids 5000+), stored in the same table as
--     delivery destinations because city customers address themselves by thana
-- Source of truth: artifacts/api-server/supabase/seed.sql, generated by
-- scripts/src/generate-bd-geo.mjs. This migration only adds rows/columns; no
-- existing district, upazila or order id changes.
-- ============================================================================

ALTER TABLE upazilas
  ADD COLUMN IF NOT EXISTS is_metropolitan_thana BOOLEAN NOT NULL DEFAULT FALSE;

COMMENT ON COLUMN upazilas.is_metropolitan_thana IS
  'TRUE for metropolitan police thanas (Dhaka, Chattogram, Khulna, Rajshahi, Sylhet, Barishal, Rangpur, Gazipur, Narayanganj) used as delivery destinations.';

CREATE INDEX IF NOT EXISTS idx_upazilas_is_metropolitan_thana
  ON upazilas(is_metropolitan_thana);

-- Newly approved upazilas (2026-05-07). Names mirror seed.sql.
INSERT INTO upazilas (id, district_id, name_en, name_bn, url, is_active, is_metropolitan_thana)
VALUES
  (495, 14, 'Mokamtola', 'মোকামতলা', 'null', TRUE, FALSE),
  (496, 9, 'Matamuhuri', 'মাতামুহুরী', 'null', TRUE, FALSE),
  (497, 58, 'Ruhia', 'রুহিয়া', 'null', TRUE, FALSE),
  (498, 58, 'Bhulli', 'ভুল্লী', 'null', TRUE, FALSE),
  (499, 7, 'Chandraganj', 'চন্দ্রগঞ্জ', 'null', TRUE, FALSE)
ON CONFLICT (id) DO UPDATE SET
  district_id = EXCLUDED.district_id,
  name_en = EXCLUDED.name_en,
  name_bn = EXCLUDED.name_bn,
  is_metropolitan_thana = FALSE;

-- Guard: a metropolitan thana must never share an id with an official upazila.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM upazilas WHERE is_metropolitan_thana AND id < 5000
  ) THEN
    RAISE EXCEPTION 'metropolitan thana ids must stay in the 5000+ range';
  END IF;
END;
$$;

COMMIT;
